def cached(cache, key=hashkey, lock=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            if key is None:
                key = hashkey(args, kwargs)
            if key in cache:
                return cache[key]
            result = func(*args, **kwargs)
            if lock is not None:
                with lock:
                    cache[key] = result
            else:
                cache[key] = result
            return result
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = {}
        hits = misses = 0
        lock = threading.Lock()

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = (args, frozenset(kwargs.items())) if typed else args
            with lock:
                now = timer()
                try:
                    value, expire = cache[key]
                    if now < expire:
                        hits += 1
                        return value
                    else:
                        misses += 1
                except KeyError:
                    misses += 1
            value = func(*args, **kwargs)
            with lock:
                cache[key] = (value, now + ttl)
            return value

        def cache_info():
            with lock:
                return {
                    "hits": hits,
                    "misses": misses,
                    "maxsize": maxsize,
                    "size": len(cache),
                }

        wrapper.cache_info = cache_info
        return wrapper

    return decorator

def mru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        mru = []
        def wrapper(*args, **kwargs):
            key = (args, frozenset(kwargs.items())) if typed else args
            if key in cache:
                mru.remove(key)
                mru.append(key)
                return cache[key]
            else:
                result = func(*args, **kwargs)
                cache[key] = result
                mru.append(key)
                if len(cache) > maxsize:
                    cache.pop(mru.pop(0))
                return result
        return wrapper
    return decorator

def lru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        queue = []
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items()))
            if key in cache:
                return cache[key]
            result = func(*args, **kwargs)
            if typed:
                key = (type(args[0]), key)
            if len(cache) >= maxsize:
                cache.pop(queue.pop(0))
            queue.append(key)
            cache[key] = result
            return result
        return wrapper
    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if len(self) == 0:
        raise KeyError("popitem(): dictionary is empty")
    else:
        key = next(iter(self))
        value = self[key]
        del self[key]
        return (key, value)

def setdefault(self, key, default=None):
    if key not in self:
        self[key] = default
    return self.get(key, default)

def get(self, key, default=None):
    if key in self:
        return self[key]
    else:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            if lock:
                with lock:
                    key = key(*args, **kwargs)
                    if key not in cache:
                        cache[key] = func(*args, **kwargs)
            else:
                key = key(*args, **kwargs)
                if key not in cache:
                    cache[key] = func(*args, **kwargs)
            return cache[key]
        return wrapper
    return decorator

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    bases = []
    for cls in classes:
        if cls not in bases:
            bases.append(cls)
    return bases

def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface."""
    names = []
    descriptions = []
    for name, attr in self.__class__.__dict__.items():
        if isinstance(attr, Attribute):
            names.append(name)
            descriptions.append(attr.description)
    if all:
        for base in self.__class__.__bases__:
            names.extend(base.namesAndDescriptions(all))
            descriptions.extend(base.namesAndDescriptions(all))
    return names, descriptions

def names(self, all=False):
    """Return the attribute names defined by the interface."""
    return [attr.name for attr in self.attributes if all or attr.name not in self.interface.attributes]

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for arg in sequence:
        if isinstance(arg, Declaration):
            output.append(arg)
        elif isinstance(arg, tuple):
            output.extend(arg)
        elif isinstance(arg, Interface):
            output.append(arg)
        elif isinstance(arg, ImplementsSpec):
            output.append(arg)
        else:
            raise ValueError("Invalid argument type: " + str(type(arg)))
    return output

