def is_fill_request_seq(seq):
    if isinstance(seq, FillRequest):
        return True
    elif isinstance(seq, list):
        for item in seq:
            if isinstance(item, FillRequest):
                return True
        return False
    else:
        return False

def difference(d1, d2, level=-1):
    if level == -1:
        return {k: v for k, v in d1.items() if k not in d2}
    else:
        result = {}
        for k, v in d1.items():
            if k not in d2:
                result[k] = v
            elif isinstance(v, dict):
                result[k] = difference(v, d2[k], level-1)
            elif v != d2[k]:
                result[k] = v
        return result

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """

    error_messages = []

    for key, value in labels.items():
        if not isinstance(key, str):
            error_messages.append({"key": str(key), "value": "expected string or bytes-like object"})
        if not isinstance(value, (str, list)):
            error_messages.append({"value": str(value), "value": "expected string or bytes-like object"})
        if isinstance(value, list):
            for item in value:
                if not isinstance(item, str):
                    error_messages.append({"value": str(item), "value": "expected string or bytes-like object"})

    if error_messages:
        raise ValidationError(error_messages)

