def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if extract_spec_version:
        spec_version = self.get_spec_version(inventory)
    else:
        spec_version = self.spec_version

    # Check if the inventory is a valid JSON object
    if not isinstance(inventory, dict):
        raise ValueError("Inventory is not a valid JSON object")

    # Check if the inventory has the required fields
    required_fields = ["type", "version", "metadata", "items"]
    for field in required_fields:
        if field not in inventory:
            raise ValueError(f"Inventory is missing required field: {field}")

    # Check if the type value is valid
    if inventory["type"] != "inventory":
        raise ValueError(f"Inventory has invalid type value: {inventory['type']}")

    # Check if the version value is valid
    if inventory["version"] != spec_version:
        raise ValueError(f"Inventory has invalid version value: {inventory['version']}")

    # Check if the metadata field is a valid JSON object
    if not isinstance(inventory["metadata"], dict):
        raise ValueError("Inventory metadata is not a valid JSON object")

    # Check if the items field is a valid JSON array
    if not isinstance(inventory["items"], list):
        raise ValueError("Inventory items is not a valid JSON array")

    # Check if the items field has at least one item
    if len(inventory["items"]) == 0:
        raise ValueError("Inventory items is empty")

    # Check if each item in the items field is a valid JSON object
    for item in inventory["items"]:
        if not isinstance(item, dict):
            raise ValueError("Inventory item is not a valid JSON object")

        # Check if each item has the required fields
        required_fields = ["id", "name", "description", "quantity"]
        for field in required_fields:
            if field not in item:
                raise ValueError(f"Inventory item is missing required field: {field}")

        # Check if the id field is a valid string
        if not isinstance(item["id"], str):
            raise ValueError("Inventory item id is not a valid string")

        # Check if the name field is a valid string
        if not isinstance(item["name"], str):
            raise ValueError("Inventory item name is not a valid string")

        # Check if the description field is a valid string
        if not isinstance(item["description"], str):
            raise ValueError("Inventory item description is not a valid string")

        # Check if the quantity field is a valid integer
        if not isinstance(item["quantity"], int):
            raise ValueError("Inventory item quantity is not a valid integer")

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    for manifest_file in manifest_files:
        with open(manifest_file, "r") as f:
            manifest = json.load(f)
        for digest in manifest["digests"]:
            if digest not in digests_used:
                raise ValueError(f"Digest {digest} is not used in the manifest")
            if digest not in self.digests:
                raise ValueError(f"Digest {digest} is not present in the manifest")

