def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Check if the fixity block is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Check if the fixity block has the required keys
    required_keys = ["type", "algorithm", "value"]
    for key in required_keys:
        if key not in fixity:
            raise ValueError(f"Fixity block must have the key {key}")

    # Check if the fixity type is valid
    if fixity["type"] not in ["md5", "sha1", "sha256"]:
        raise ValueError(f"Fixity type must be one of md5, sha1, or sha256")

    # Check if the fixity algorithm is valid
    if fixity["algorithm"] not in ["md5", "sha1", "sha256"]:
        raise ValueError(f"Fixity algorithm must be one of md5, sha1, or sha256")

    # Check if the fixity value is a string
    if not isinstance(fixity["value"], str):
        raise ValueError("Fixity value must be a string")

    # Check if the fixity value is a valid hash
    if not re.match(r"^[a-fA-F0-9]{32}$", fixity["value"]):
        raise ValueError("Fixity value must be a valid hash")

    # Check if the manifest files are valid
    for file in manifest_files:
        if not isinstance(file, str):
            raise ValueError("Manifest files must be strings")

        if not re.match(r"^[a-zA-Z0-9\-\._]+$", file):
            raise ValueError("Manifest files must be valid file names")

    # Check if the fixity block references a valid file in the manifest
    if fixity["value"] not in manifest_files:
        raise ValueError("Fixity block must reference a valid file in the manifest")

    return True

