        print("Pretty printing element " + self.id)
    result = ""
    if self.id:
        result += "id=" + self.id + "\n"
    if self.text:
        result += "text=" + self.text + "\n"
    if self.doc:
        result += "doc=" + self.doc.id + "\n"
    if self.parent:
        result += "parent=" + self.parent.id + "\n"
    if self.children:
        result += "children=" + ", ".join([child.id for child in self.children]) + "\n"
    if self.attributes:
        result += "attributes=" + ", ".join([attr.name for attr in self.attributes]) + "\n"
    if self.annotations:
        result += "annotations=" + ", ".join([ann.name for ann in self.annotations]) + "\n"
    return result

def absorb(self, args):
    new_args = []
    for arg in args:
        if isinstance(arg, And):
            if arg.left == arg.right:
                new_args.append(arg.left)
            elif arg.left == Not(arg.right):
                new_args.append(arg.left)
            else:
                new_args.append(arg)
        elif isinstance(arg, Or):
            if arg.left == arg.right:
                new_args.append(arg.left)
            elif arg.left == Not(arg.right):
                new_args.append(arg.left)
            else:
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def wrapper():
        result = namefunc()
        if isinstance(result, str):
            return result.encode('utf-8')
        else:
            return result
    return wrapper

