        inventory_path = os.path.join(version_dir, "inventory.json")
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Inventory file not found at {inventory_path}")
        with open(inventory_path, "r") as f:
            inventory = json.load(f)
        if not inventory:
            raise ValueError(f"Inventory file at {inventory_path} is empty")
        if version_dir == "root":
            root_inventory = inventory
        else:
            if not all(item in root_inventory for item in inventory):
                raise ValueError(f"Inventory file at {inventory_path} has items not present in the root inventory")
        content_digests = set(inventory.values())
        if version_dir != "root":
            self.content_digests.update(content_digests)

def find_path_type(path):
