def deep_merge_nodes(nodes):
    merged_nodes = []
    for node in nodes:
        key, value = node
        if key in [n[0] for n in merged_nodes]:
            # If the key is already in the merged nodes, merge the values
            for i, n in enumerate(merged_nodes):
                if n[0] == key:
                    merged_nodes[i] = (key, deep_merge_nodes([value, n[1]]))
                    break
        else:
            # If the key is not in the merged nodes, add it
            merged_nodes.append(node)
    return merged_nodes

