def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None
    else:
        match = re.match(r"(\d+) (\w+)", frequency)
        if match:
            num = int(match.group(1))
            unit = match.group(2)
            if unit == "weeks":
                return datetime.timedelta(weeks=num)
            elif unit == "days":
                return datetime.timedelta(days=num)
            elif unit == "hours":
                return datetime.timedelta(hours=num)
            elif unit == "minutes":
                return datetime.timedelta(minutes=num)
            elif unit == "seconds":
                return datetime.timedelta(seconds=num)
            else:
                raise ValueError("Invalid frequency unit: " + unit)
        else:
            raise ValueError("Invalid frequency format: " + frequency)

