def scale(self, other=None, recompute=False):
    if other is None:
        if self.scale is None or recompute:
            self.scale = self.integrate()
        return self.scale
    else:
        if self.scale == 0:
            raise LenaValueError("Histograms with scale equal to zero can't be rescaled.")
        self.scale = other
        self.data = self.data * other

def scale(self, other=None):
    if other is None:
        return self.scale
    elif isinstance(other, (int, float)):
        if self.scale == 0:
            raise LenaValueError("Cannot rescale graph with unknown scale")
        self.scale = other
        for field in self.fields:
            if field.name == "x":
                field.value *= other
            elif field.name == "y":
                field.value *= other
            elif field.name == "z":
                field.value *= other
        for error in self.errors:
            error.value *= other
    else:
        raise TypeError("other must be a number")

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    """Convert a histogram to a graph.

    Args:
        hist (list): A list of histogram bins.
        make_value (function, optional): A function to set the value of a graph point. Defaults to None.
        get_coordinate (str, optional): Defines what the coordinate of a graph point created from a histogram bin will be. Defaults to "left".
        field_names (tuple, optional): Set field names of the graph. Defaults to ("x", "y").
        scale (bool, optional): Becomes the graph's scale. Defaults to None.

    Returns:
        graph: The resulting graph.
    """
    if not make_value:
        make_value = lambda bin_: bin_.content

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("Invalid get_coordinate argument")

    if len(field_names) != 2:
        raise ValueError("Invalid field_names argument")

    graph = []
    for bin_ in hist:
        if not isinstance(bin_, NumericBin):
            raise ValueError("Histogram must contain only numeric bins")

        if get_coordinate == "left":
            x = bin_.left
        elif get_coordinate == "right":
            x = bin_.right
        else:
            x = (bin_.left + bin_.right) / 2

        y = make_value(bin_)

        graph.append((x, y))

    if scale:
        graph.scale = scale

    return graph

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """

    if not tentative:
        if not iface.providedBy(candidate):
            raise zope.interface.Invalid("Candidate does not claim to provide the interface")

    for name, spec in iface.namesAndDescriptions():
        if spec.required:
            if not hasattr(candidate, name):
                raise zope.interface.Invalid("Candidate does not define required attribute %s" % name)

    for name, spec in iface.namesAndDescriptions():
        if spec.required:
            if not hasattr(candidate, name):
                raise zope.interface.Invalid("Candidate does not define required method %s" % name)

    for name, spec in iface.namesAndDescriptions():
        if spec.required:
            if not hasattr(candidate, name):
                raise zope.interface.Invalid("Candidate does not define required method %s" % name)

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(candidate, iface):
        return False
    if not tentative:
        if not hasattr(candidate, "__implements__"):
            return False
        if not isinstance(candidate.__implements__, list):
            return False
        if iface not in candidate.__implements__:
            return False
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    if explicit_mc is not None:
        return explicit_mc
    else:
        for base in bases:
            if hasattr(base, "__metaclass__"):
                return base.__metaclass__
        return type

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Find the key with the lowest frequency
    min_freq = float('inf')
    min_key = None
    for key, value in self.items():
        if value < min_freq:
            min_freq = value
            min_key = key

    # Remove the key and return it
    del self[min_key]
    return (min_key, min_freq)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if len(self) == 0:
        raise KeyError("Cache is empty")
    else:
        key = self.order[0]
        value = self.data[key]
        del self.data[key]
        self.order.pop(0)
        return (key, value)

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if len(self) == 0:
        raise KeyError("popitem(): dictionary is empty")
    key = random.choice(list(self.keys()))
    value = self.pop(key)
    return (key, value)

