def default_tzinfo(dt, tzinfo):
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=tzinfo)
    return dt

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    if request.type == "public_message":
        return True
    elif request.type == "private_message":
        return True
    elif request.type == "legacy_payload":
        return True
    else:
        return False

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    code_block = False
    for word in text.split():
        if word == "```":
            code_block = not code_block
            continue
        if code_block:
            continue
        if word.startswith("#"):
            tags.add(word[1:])
            if replacer:
                text = text.replace(word, replacer(word))
    return tags, text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    links = re.findall(r"\[([^\]]+)\]\(([^)]+)\)", text)
    for link in links:
        text = text.replace(link[0], f"<a href='{link[1]}'>{link[0]}</a>")
    return text

