def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    children = {}
    for child in node.children:
        if child.tag not in children:
            children[child.tag] = []
        children[child.tag].append(child)
    return children

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    if sender_handle != entity_handle:
        raise ValueError("Sender handle and entity handle do not match.")

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """

    # Check if the url is valid
    if not url.startswith("http"):
        raise ValueError("Invalid URL: " + url)

    # Check if the document_path is valid
    if document_path and not document_path.startswith("/"):
        raise ValueError("Invalid document path: " + document_path)

    # Generate the NodeInfo document
    nodeinfo_document = {
        "links": {
            "self": {
                "href": url + (document_path or "/.well-known/nodeinfo"),
                "type": "application/json"
            }
        }
    }

    # Add the NodeInfo version
    nodeinfo_document["version"] = "1.0"

    # Add the NodeInfo protocols
    nodeinfo_document["protocols"] = ["activitypub"]

    # Add the NodeInfo services
    nodeinfo_document["services"] = {
        "inbound": [],
        "outbound": []
    }

    # Add the NodeInfo metadata
    nodeinfo_document["metadata"] = {
        "node": {
            "name": "NodeInfo",
            "summary": "NodeInfo is a protocol for discovering information about a node on the internet.",
            "url": url,
            "links": {
                "self": {
                    "href": url + (document_path or "/.well-known/nodeinfo"),
                    "type": "application/json"
                }
            }
        }
    }

    return nodeinfo_document

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Verify the signature using the public key
    if not public_key.verify(signature, doc.to_xml()):
        raise ValueError("Invalid signature")

    # Verify that the signed elements are not tampered with
    signed_elements = doc.findall(".//*[@signature]")
    for signed_element in signed_elements:
        if not signed_element.get("signature") == signature:
            raise ValueError("Signed element has been tampered with")

    # Verify that the signed elements are not duplicated
    signed_element_ids = [signed_element.get("id") for signed_element in signed_elements]
    if len(signed_element_ids) != len(set(signed_element_ids)):
        raise ValueError("Duplicate signed elements found")

    # Verify that the signed elements are not empty
    for signed_element in signed_elements:
        if not signed_element.text:
            raise ValueError("Signed element is empty")

    # Verify that the signed elements are not too long
    for signed_element in signed_elements:
        if len(signed_element.text) > 1000:
            raise ValueError("Signed element is too long")

    # Verify that the signed elements are not too short
    for signed_element in signed_elements:
        if len(signed_element.text) < 10:
            raise ValueError("Signed element is too short")

    # Verify that the signed elements are not too similar
    for i in range(len(signed_elements)):
        for j in range(i + 1, len(signed_elements)):
            if jaccard_similarity(signed_elements[i].text, signed_elements[j].text) > 0.8:
                raise ValueError("Signed elements are too similar")

    # Verify that the signed elements are not too dissimilar
    for i in range(len(signed_elements)):
        for j in range(i + 1, len(signed_elements)):
            if jaccard_similarity(signed_elements[i].text, signed_elements[j].text) < 0.2:
                raise ValueError("Signed elements are too dissimilar")

    # Verify that the signed elements are not too similar to each other
    for i in range(len(signed_elements)):
        for j in range(i + 1, len(signed_elements)):
            if jaccard_similarity(signed_elements[i].text, signed_elements[j].text) > 0.8:
                raise ValueError("Signed elements are too similar")

    # Verify that the signed elements are not too dissimilar to each other
    for i in range(len(signed_elements)):
        for j in range(i + 1, len(signed_elements)):
            if jaccard_similarity(signed_elements[i].text, signed_elements[j].text) < 0.2:
                raise ValueError("Signed elements are too dissimilar")

