def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if document.startswith('<?xml'):
        # Parse XRD format
        root = ET.fromstring(document)
        ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
        xrd = root.find('xrd:XRD', ns)
        if xrd is None:
            raise ValueError('Invalid XRD format')
        webfinger = {}
        for subject in xrd.findall('xrd:Subject', ns):
            webfinger[subject.text] = {}
            for property in subject.findall('xrd:Property', ns):
                webfinger[subject.text][property.attrib['name']] = property.text
        return webfinger
    else:
        # Parse JSON format
        webfinger = json.loads(document)
        if 'subject' not in webfinger or 'aliases' not in webfinger or 'links' not in webfinger:
            raise ValueError('Invalid JSON format')
        return webfinger

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    try:
        response = requests.get(f"https://{handle}.webfinger")
        if response.status_code == 200:
            return response.text
        else:
            return None
    except requests.exceptions.RequestException:
        return None

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    url = "https://" + host + "/host-meta"
    response = requests.get(url)
    if response.status_code == 200:
        return XRD.from_xml(response.text)
    else:
        raise Exception("Unable to retrieve host-meta document from " + host)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    file_names = []
    for settings_dir in settings_dirs:
        for root, dirs, files in os.walk(settings_dir):
            for file in files:
                if file.endswith(".ini"):
                    file_names.append(os.path.join(root, file))
    return file_names

